"use client"

import type React from "react"
import { useState, useEffect, useRef } from "react"
import Image from "next/image"
import {
  Home,
  BookOpen,
  Calendar,
  ChevronLeft,
  ChevronRight,
  Clock,
  LogOut,
  Plus,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"

import { collection, addDoc, getDocs, deleteDoc, doc } from "firebase/firestore"
import { auth, db } from "@/lib/firebase"

/* ================= TYPES ================= */

interface JadwalPageProps {
  onLogout: () => void
  onNavigate: (page: "home" | "edukasi" | "jadwal") => void
}

interface MedicationSchedule {
  id: string
  date: string
  time: string
  medicines: string[]
  taken: boolean
  notified?: boolean
}

interface UserData {
  nama: string
  email: string
}

/* ================= COMPONENT ================= */

export default function JadwalPage({ onLogout, onNavigate }: JadwalPageProps) {
  const [currentUser, setCurrentUser] = useState<UserData | null>(null)
  const [selectedDate, setSelectedDate] = useState(new Date())
  const [currentMonth, setCurrentMonth] = useState(new Date())
  const [schedules, setSchedules] = useState<MedicationSchedule[]>([])

  const [openAdd, setOpenAdd] = useState(false)
  const [startDate, setStartDate] = useState("")
  const [endDate, setEndDate] = useState("")
  const [time, setTime] = useState("09:00")
  const [medicines, setMedicines] = useState<string[]>(["Isoniazid"])

  const [showSuccessPopup, setShowSuccessPopup] = useState(false)
  const triggeredRef = useRef<Set<string>>(new Set())

  /* ================= INIT USER ================= */
  useEffect(() => {
    const u = localStorage.getItem("tbcare_current_user")
    if (u) setCurrentUser(JSON.parse(u))
  }, [])

  /* ================= LOAD FIRESTORE ================= */
  useEffect(() => {
    const load = async () => {
      const user = auth.currentUser
      if (!user) return

      const snap = await getDocs(collection(db, "users", user.uid, "reminders"))
      const data = snap.docs.map(d => ({
        id: d.id,
        ...(d.data() as Omit<MedicationSchedule, "id">),
      }))

      setSchedules(data)
    }

    load()
  }, [])

  /* ================= ALARM ================= */
  useEffect(() => {
    const interval = setInterval(() => {
      const now = new Date()

      setSchedules(prev =>
        prev.map(s => {
          if (s.taken || s.notified) return s

          const key = `${s.date}_${s.time}`
          if (triggeredRef.current.has(key)) return s

          const alarm = new Date(`${s.date}T${s.time}`)
          const diff = now.getTime() - alarm.getTime()

          if (diff >= 0 && diff <= 120000) {
            triggeredRef.current.add(key)
            alert(`⏰ ${formatDate(s.date)} – ${s.medicines.join(", ")}`)
            return { ...s, notified: true }
          }
          return s
        }),
      )
    }, 30000)

    return () => clearInterval(interval)
  }, [])

  /* ================= HELPERS ================= */

  const formatDate = (d: string) =>
    new Date(d).toLocaleDateString("id-ID", {
      weekday: "long",
      day: "2-digit",
      month: "long",
      year: "numeric",
    })

  const getMonthName = (d: Date) =>
    d.toLocaleDateString("en-US", { month: "long", year: "numeric" })

  const getDaysInMonth = (d: Date) => {
    const y = d.getFullYear()
    const m = d.getMonth()
    return {
      days: new Date(y, m + 1, 0).getDate(),
      start: new Date(y, m, 1).getDay(),
      y,
      m,
    }
  }

  const renderCalendar = () => {
    const { days, start, y, m } = getDaysInMonth(currentMonth)
    const cells: React.ReactNode[] = []
    const selected = selectedDate.toISOString().split("T")[0]

    for (let i = 0; i < start; i++) cells.push(<div key={`e-${i}`} />)

    for (let d = 1; d <= days; d++) {
      const date = `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`
      const has = schedules.some(s => s.date === date)
      const isSelected = date === selected

      cells.push(
        <button
          key={date}
          onClick={() => setSelectedDate(new Date(date))}
          className={`h-9 rounded-lg text-sm flex items-center justify-center
            ${isSelected ? "bg-[#4a90d9] text-white" : has ? "bg-blue-100" : "hover:bg-gray-100"}
          `}
        >
          {d}
        </button>,
      )
    }
    return cells
  }

  /* ================= ADD ================= */

  const handleAdd = async () => {
    const user = auth.currentUser
    if (!user || !startDate) return

    const s = new Date(startDate)
    const e = endDate ? new Date(endDate) : s

    for (let d = new Date(s); d <= e; d.setDate(d.getDate() + 1)) {
      const payload = {
        date: d.toISOString().split("T")[0],
        time,
        medicines: medicines.filter(m => m.trim()),
        taken: false,
        notified: false,
      }

      const ref = await addDoc(collection(db, "users", user.uid, "reminders"), payload)
      setSchedules(prev => [...prev, { id: ref.id, ...payload }])
    }

    setOpenAdd(false)
    setStartDate("")
    setEndDate("")
    setMedicines(["Isoniazid"])
  }

  /* ================= MARK AS TAKEN (FINAL) ================= */

  const handleMarkAsTaken = async (id: string) => {
    const user = auth.currentUser
    if (!user) return

    setSchedules(prev => prev.filter(s => s.id !== id))
    await deleteDoc(doc(db, "users", user.uid, "reminders", id))

    setShowSuccessPopup(true)
  }

  const selectedSchedules = schedules.filter(
    s => s.date === selectedDate.toISOString().split("T")[0],
  )

  /* ================= RENDER ================= */

  return (
    <div className="min-h-screen bg-[#f8fafc] flex">
      {/* SIDEBAR & MAIN & BOTTOM BAR — TIDAK DIUBAH */}

      {/* ===== MAIN ===== */}
      <div className="flex-1 lg:ml-64 p-4 lg:p-8 space-y-4 pb-24">
        <div className="bg-white rounded-2xl p-4">
          <div className="flex justify-between items-center mb-3">
            <Button size="icon" variant="ghost" onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth() - 1)))}>
              <ChevronLeft />
            </Button>
            <h3 className="font-bold">{getMonthName(currentMonth)}</h3>
            <Button size="icon" variant="ghost" onClick={() => setCurrentMonth(new Date(currentMonth.setMonth(currentMonth.getMonth() + 1)))}>
              <ChevronRight />
            </Button>
          </div>
          <div className="grid grid-cols-7 gap-1">{renderCalendar()}</div>
        </div>

        <Button className="bg-[#4a90d9]" onClick={() => setOpenAdd(true)}>
          <Plus className="w-4 h-4 mr-2" /> Tambah Reminder
        </Button>

        {selectedSchedules.map(s => (
          <div key={s.id} className="bg-[#ffd4b3] border border-orange-200 rounded-2xl p-4 space-y-2">
            <p className="font-semibold">💊 Saatnya Minum Obat</p>
            <p className="text-sm">{s.medicines.join(", ")}</p>
            <div className="flex items-center gap-2">
              <Clock className="w-4 h-4 text-blue-600" />
              <span className="font-bold text-blue-600">{s.time}</span>
            </div>

            <Button
              className="w-full bg-[#51cf66] hover:bg-[#47b85d] text-white"
              onClick={() => handleMarkAsTaken(s.id)}
            >
              Sudah Minum Obat
            </Button>
          </div>
        ))}
      </div>

      {/* SUCCESS POPUP */}
      <Dialog open={showSuccessPopup} onOpenChange={setShowSuccessPopup}>
        <DialogContent className="max-w-sm">
          <div className="text-center space-y-4 py-6">
            <p className="text-lg font-semibold">🎉 Kamu sudah minum obat!</p>
            <Button onClick={() => setShowSuccessPopup(false)}>Mengerti</Button>
          </div>
        </DialogContent>
      </Dialog>
    </div>
  )
}
